('b9e855b5-886b-552f-b299-b1d342e52636', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Ev wêne ji bo "rê" ye: berambera rast kîjan e?', 'leğen', 'ben', 'yol', 'eski', 'C', '"rê" "yol" demektir.', NULL, NULL, 2, true, 'visual', 'asset://assets/question_images/re.webp', NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_0060
